posts.body:
I added a couple of lines to the refresh to draw the title.
And I added to the windowHeight and set the windowWidth as fixed, since I assume it's used with picture background (from the Triacontane plugin).
You can set the title name before the message with a script box:
$gameTemp._titleName = "MASTER";
I'm not familiar with the codes checking for the tags inside the message window, so I made it like that. If you want a message box tag, ask someone else or AI LOL.
Copy paste the below in notepad, save as .js file and add as a plugin (you can add lines to change the color or font size etc if you want):
Window_NameBox.prototype.windowHeight = function() {
return 120;
};
Window_NameBox.prototype.windowWidth = function() {
return 200;
};
Window_NameBox.prototype.refresh = function(text, position) {
const titleName = $gameTemp._titleName || "";
this.show();
this._lastNameText = text;
this._text = Yanfly.Param.MSGNameBoxText + text;
this._position = position;
this.width = this.windowWidth();
this.createContents();
this.contents.clear();
this.resetFontSettings();
this.changeTextColor(this.textColor(Yanfly.Param.MSGNameBoxColor));
var padding = eval(Yanfly.Param.MSGNameBoxPadding) / 2;
this.drawTextEx(titleName, padding, 0, this.contents.width);
this.drawTextEx(this._text, padding, 50, this.contents.width);
this._parentWindow.adjustWindowSettings();
this._parentWindow.updatePlacement();
this.adjustPositionX();
this.adjustPositionY();
this.open();
this.activate();
this._closeCounter = 4;
return '';
};
